90: function nextBet(s) {
91:   const c = s.bot.config;
92:   const base = s.startedBalance * c.basePct / 100;
93:   const lossStep = s.bot.stats.lossStreak;
94:   let bet = base;
95:   if (c.mode === 'capped-recovery') bet = lossStep >= c.lossReset ? base : base * Math.pow(c.lossMult, lossStep);
96:   if (c.mode === 'bounded-ladder') {
97:     const fib = [1, 1, 2, 3, 5, 8, 13];
98:     bet = base * fib[Math.min(lossStep, c.lossReset)];
99:   }
100:   // Flat mode: bet tetap, tidak ada kenaikan pasca-kalah
101:   // Bulatkan ke bawah ke satuan minbet
102:   const minBet = apiSetting(s, 'MinBet', 'MinBetAmount');
103:   if (minBet !== null && minBet > 0) bet = Math.floor(bet / minBet) * minBet;
104:   return Math.min(bet, s.startedBalance * c.maxBetPct / 100, maxLiveBet || Infinity);
105: }
