140: async function botTick(s, runId = s.bot.runId) {
141:   if (!s.bot.running || s.bot.runId !== runId || s.bot.paused) return;
142:   const c = s.bot.config;
143:   if (s.bot.stats.rolls >= c.maxRolls) {
144:     clearBot(s, `Selesai: mencapai batas ${c.maxRolls} rolls.`);
145:     return;
146:   }
147:   const netPnl = Number(s.bot.stats.profit || 0);
148:   const currentBalance = s.balance?.Balance ?? s.startedBalance;
149:   // Cek floor balance: stop-loss awal atau breakeven setelah lock
150:   if (currentBalance <= s.bot.floorBalance) {
151:     const floorPct = ((s.bot.floorBalance / s.startedBalance - 1) * 100).toFixed(2);
152:     clearBot(s, `STOP: saldo mencapai floor ${floorPct}% dari bankroll awal.`);
153:     return;
154:   }
155:   // Lock breakeven: setelah profit mencapai lockBreakevenAfterPct%, floor dinaikkan ke bankroll awal
156:   if (!s.bot.locked && c.lockBreakevenAfterPct > 0 && netPnl >= s.startedBalance * c.lockBreakevenAfterPct / 100) {
157:     s.bot.floorBalance = s.startedBalance;
158:     s.bot.locked = true;
159:     s.bot.stopReason = `LOCK BREAK EVEN: profit +${c.lockBreakevenAfterPct}% tercapai, floor dikunci ke bankroll awal.`;
160:   }
161:   if (c.takeProfitPct > 0 && s.bot.cycleProfit >= s.startedBalance * c.takeProfitPct / 100) {
162:     pauseForTarget(s, runId);
163:     return;
164:   }
165:   if (s.bot.stats.lossStreak >= c.maxLossStreak) {
166:     clearBot(s, `STOP: ${c.maxLossStreak} kekalahan beruntun mencapai batas strategi.`);
167:     return;
168:   }
169:   const bet = nextBet(s);
170:   if (!Number.isFinite(bet) || bet <= 0) {
171:     clearBot(s, 'Berhenti: bet amount tidak valid atau saldo tidak mencukupi.');
172:     return;
173:   }
174:   const betValidation = validateBetAgainstSettings(s, bet, c.payout);
175:   if (betValidation) {
176:     clearBot(s, `API menolak konfigurasi taruhan: ${betValidation}`);
177:     return;
178:   }
179:   try {
180:     const result = await cg(`/placebet/${encodeURIComponent(s.coin)}/${encodeURIComponent(s.apiKey)}`, {
181:       method: 'POST',
182:       body: JSON.stringify({ Bet: Number(bet.toFixed(8)), Payout: c.payout, UnderOver: c.under, ClientSeed: crypto.randomBytes(16).toString('hex') })
183:     });
184:     const profit = Number(result.Profit || 0);
185:     const st = s.bot.stats;
186:     st.transientErrors = 0;
187:     st.errors = 0;
188:     st.lastError = null;
189:     st.rolls++;
190:     st.profit += profit;
191:     s.bot.cycleProfit += profit;
192:     st.wins += profit > 0 ? 1 : 0;
193:     st.losses += profit > 0 ? 0 : 1;
194:     st.lossStreak = profit > 0 ? 0 : st.lossStreak + 1;
195:     st.winStreak = profit > 0 ? st.winStreak + 1 : 0;
196:     st.maxLossStreak = Math.max(st.maxLossStreak, st.lossStreak);
197:     st.maxWinStreak = Math.max(st.maxWinStreak, st.winStreak);
198:     st.wagered += bet;
199:     s.sessionLoss += Math.max(0, -profit);
200:     const roll = rollValue(result);
201:     const highLow = rollDirection(result, roll, c.under);
202:     if (result.Balance !== undefined || result.balance !== undefined) s.balance = { ...s.balance, Balance: result.Balance ?? result.balance };
203:     st.last = { profit, bet, balance: s.balance?.Balance ?? null, result: roll, hiLow: highLow, at: Date.now() };
204:   } catch (e) {
205:     const transient = /Crypto\.Games HTTP (502|503|504)|fetch failed|timed out|UND_ERR/i.test(e.message);
206:     s.bot.stats.lastError = e.message;
207:     if (transient) {
208:       s.bot.stats.transientErrors = (s.bot.stats.transientErrors || 0) + 1;
209:       s.bot.stats.errors = s.bot.stats.transientErrors;
210:       const retryMs = Math.min(60000, c.delayMs * Math.pow(2, Math.min(s.bot.stats.transientErrors - 1, 4)));
211:       s.bot.stopReason = `API sementara gagal (${e.message}) · retry dalam ${Math.ceil(retryMs / 1000)} detik.`;
212:       if (s.bot.running && s.bot.runId === runId && !s.bot.paused) s.bot.timer = setTimeout(() => void botTick(s, runId), retryMs);
213:       return;
214:     }
