import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const OUT = process.argv[2];
if (!OUT) throw new Error('Usage: node generate-icons.mjs <out-dir>');
fs.mkdirSync(OUT, { recursive: true });

const SS = 4;
const crcTable = new Uint32Array(256);
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  crcTable[n] = c >>> 0;
}
function crc32(buf) {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function chunk(type, data) {
  const name = Buffer.from(type, 'ascii');
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([name, data])));
  return Buffer.concat([len, name, data, crc]);
}
function encodePNG(width, height, rgba) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  const raw = Buffer.alloc((width * 4 + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (width * 4 + 1)] = 0;
    rgba.copy(raw, y * (width * 4 + 1) + 1, y * width * 4, (y + 1) * width * 4);
  }
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk('IHDR', ihdr),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0))
  ]);
}

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const mix = (a, b, t) => a + (b - a) * t;

function render(size, maskable) {
  const n = size * SS;
  const buf = new Float32Array(n * n * 4);
  const px = (x, y, r, g, b, a = 1) => {
    if (x < 0 || y < 0 || x >= n || y >= n || a <= 0) return;
    const i = (y * n + x) * 4;
    const da = buf[i + 3];
    const outA = a + da * (1 - a);
    if (outA <= 0) { buf.fill(0, i, i + 4); return; }
    buf[i] = (r * a + buf[i] * da * (1 - a)) / outA;
    buf[i + 1] = (g * a + buf[i + 1] * da * (1 - a)) / outA;
    buf[i + 2] = (b * a + buf[i + 2] * da * (1 - a)) / outA;
    buf[i + 3] = outA;
  };
  const rrSDF = (x, y, cx, cy, half, radius, angle = 0) => {
    const dx = x - cx, dy = y - cy;
    const c = Math.cos(-angle), s = Math.sin(-angle);
    const lx = dx * c - dy * s, ly = dx * s + dy * c;
    const qx = Math.abs(lx) - (half - radius);
    const qy = Math.abs(ly) - (half - radius);
    return Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - radius;
  };
  const inEllipse = (x, y, cx, cy, rx, ry) => {
    const dx = (x - cx) / rx, dy = (y - cy) / ry;
    return dx * dx + dy * dy <= 1;
  };
  const inPoly = (x, y, pts) => {
    let inside = false;
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const [xi, yi] = pts[i], [xj, yj] = pts[j];
      if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
    }
    return inside;
  };

  const u = size / 512;
  const half = 128 * u, dieCx = 250 * u, dieCy = 247 * u;
  const angle = -12 * Math.PI / 180;
  const r = maskable ? 118 * u : 128 * u;
  const radius = 52 * u;
  const pipR = 18 * u;
  const pipD = 61 * u;

  // background
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const fx = (x + 0.5) / n, fy = (y + 0.5) / n;
      const t = clamp((fx * 0.35 + fy * 0.65), 0, 1);
      const bgR = mix(42, 17, t), bgG = mix(42, 17, t), bgB = mix(42, 17, t);
      if (maskable) {
        px(x, y, bgR / 255, bgG / 255, bgB / 255, 1);
      } else {
        if (rrSDF(x + 0.5, y + 0.5, n / 2, n / 2, n / 2, 112 * u * SS) <= 0) {
          px(x, y, bgR / 255, bgG / 255, bgB / 255, 1);
        }
      }
    }
  }

  // top glow
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const dx = (x - n * 0.38) / (n * 0.6), dy = (y - n * 0.05) / (n * 0.45);
      const d = Math.hypot(dx, dy);
      if (d < 1) px(x, y, 1, 0.86, 0.3, 0.07 * (1 - d) ** 2);
    }
  }

  // soft shadow under the die
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const dx = (x - dieCx) / (156 * u * SS), dy = (y - (dieCy + 140 * u)) / (30 * u * SS);
      const d = dx * dx + dy * dy;
      if (d <= 1) px(x, y, 0, 0, 0, 0.32 * (1 - d) ** 1.4);
    }
  }

  // dice body + border
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const sdf = rrSDF(x + 0.5, y + 0.5, dieCx, dieCy, half, radius, angle);
      if (sdf <= 0) {
        const gx = (x + 0.5 - (dieCx - half)) / (half * 2);
        const gy = (y + 0.5 - (dieCy - half)) / (half * 2);
        const t = clamp((gx * 0.3 + gy * 0.7), 0, 1);
        px(x, y, mix(1, 0.95, t), mix(0.9, 0.65, t), mix(0.38, 0.02, t), 1);
      } else if (Math.abs(sdf) < 1.8 * SS) {
        px(x, y, 1, 0.96, 0.7, 0.5 * (1 - Math.abs(sdf) / (1.8 * SS)));
      }
    }
  }

  // pips
  const pips = [[-1, -1], [1, -1], [0, 0], [-1, 1], [1, 1]];
  for (const [ox, oy] of pips) {
    const px0 = dieCx + ox * pipD * Math.cos(angle) - oy * pipD * Math.sin(angle);
    const py0 = dieCy + ox * pipD * Math.sin(angle) + oy * pipD * Math.cos(angle);
    for (let y = Math.floor(py0 - pipR - 2); y <= py0 + pipR + 2; y++) {
      for (let x = Math.floor(px0 - pipR - 2); x <= px0 + pipR + 2; x++) {
        const d = Math.hypot(x + 0.5 - px0, y + 0.5 - py0);
        if (d <= pipR) px(x, y, 0.1, 0.08, 0.02, 1);
        else if (d <= pipR + 1.4 * SS) px(x, y, 1, 0.97, 0.76, 0.4 * (1 - (d - pipR) / (1.4 * SS)));
      }
    }
  }

  // sparkle
  const star = (cx, cy, rad, alpha) => {
    const pts = [
      [cx, cy - rad], [cx + rad * 0.2, cy - rad * 0.2], [cx + rad, cy],
      [cx + rad * 0.2, cy + rad * 0.2], [cx, cy + rad], [cx - rad * 0.2, cy + rad * 0.2],
      [cx - rad, cy], [cx - rad * 0.2, cy - rad * 0.2]
    ];
    for (let y = Math.floor(cy - rad - 2); y <= cy + rad + 2; y++) {
      for (let x = Math.floor(cx - rad - 2); x <= cx + rad + 2; x++) {
        if (inPoly(x + 0.5, y + 0.5, pts)) px(x, y, 1, 0.95, 0.68, alpha);
      }
    }
  };
  star(385 * u * SS, 112 * u * SS, 38 * u * SS, 0.95);
  star(343 * u * SS, 159 * u * SS, 15 * u * SS, 0.7);

  const out = Buffer.alloc(size * size * 4);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      let r = 0, g = 0, b = 0, a = 0;
      for (let sy = 0; sy < SS; sy++) {
        for (let sx = 0; sx < SS; sx++) {
          const i = (((y * SS + sy) * n) + (x * SS + sx)) * 4;
          const al = buf[i + 3];
          r += buf[i] * al; g += buf[i + 1] * al; b += buf[i + 2] * al; a += al;
        }
      }
      const o = (y * size + x) * 4;
      if (a > 0) {
        out[o] = Math.round((r / a) * 255);
        out[o + 1] = Math.round((g / a) * 255);
        out[o + 2] = Math.round((b / a) * 255);
        out[o + 3] = Math.round((a / (SS * SS)) * 255);
      }
    }
  }
  return encodePNG(size, size, out);
}

fs.writeFileSync(path.join(OUT, 'icon-192.png'), render(192, false));
fs.writeFileSync(path.join(OUT, 'icon-512.png'), render(512, false));
fs.writeFileSync(path.join(OUT, 'maskable-512.png'), render(512, true));
console.log('icons written to', OUT);

