Now sw.js. Need to handle app.js query. Precache list includes `'/app.js?v=20261027-01'` and `'/pwa.js?v=1'`. If we later add query. Also add `'/manifest.webmanifest'`.

Implement:

```js
const CACHE_NAME = 'diceforge-shell-v1';
const APP_SHELL = [...];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    await cache.addAll(APP_SHELL);
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});
```

Potential cache.addAll of `/` caches response of `/`, not `/index.html`. It separately caches index. Good.

`fetch`:
```js
self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith('/api/')) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstNavigation(request));
    return;
  }
  event.respondWith(staleWhileRevalidate(request));
});
```

Navigation:
```js
async function networkFirstNavigation(request) {
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      const cache = await caches.open(CACHE_NAME);
      cache.put('/index.html', response.clone());
    }
    return response;
  } catch {
    return (await caches.match('/index.html')) || (await caches.match('/')) || new Response(offline HTML, ...);
  }
}
```
If Server down, fallback. Note if cache.put('/index.html', response.clone()) with request having cookies, fine.

SWR:
```js
async function staleWhileRevalidate(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request);
  const network = fetch(request).then(response => {
    if (response && response.ok && response.type === 'basic') cache.put(request, response.clone());
    return response;
  }).catch(() => null);
  if (cached) { event.waitUntil(network); return cached; } // can't access event here. Better pass event or use: 
  return cached || (await network) || Response.error();
}
```
`event.waitUntil` only inside handler. Pass event into function:
```js
event.respondWith((async () => {
  const cached = await caches.match(request);
  const update = fetch(request).then(r => { ... }).catch(() => undefined);
  if (cached) { event.waitUntil(update); return cached; }
  return (await update) || new Response(...);
})());
```
If no cached and network fails for asset, return a 503 response. Fine.

Do we want to cache responses with `Cache-Control: no-store`? Cache API `.put` accepts as long as response isn't `Vary: *` and status 206 issues. Server no-store doesn't block. Good.

Offline fallback HTML should be minimal but should match app shell? Since index cached. But first install caches. Provide fallback:
```
<!doctype html><html lang=id>... offline page ... link none
```
Could simply return `caches.match('/index.html')`; the offline fallback rarely used. Provide a small inline message.

MIME for SW correct from server.

Now pwa.js. Let's write carefully.

```js
(() => {
  const standaloneMedia = window.matchMedia('(display-mode: standalone)');
  const standalone = () => standaloneMedia.matches || window.navigator.standalone === true;
  const buttons = Array.from(document.querySelectorAll('[data-install-app]'));
  let installPrompt = null;
  let dialog = null;

  const isIOS = () => /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const isAndroid = () => /Android/i.test(navigator.userAgent);
  const isSafari = () => /^((?!chrome|android|crios|fxios|edgios|opr).)*safari/i.test(navigator.userAgent); 
```
Careful regex. Simpler:
```js
const ua = navigator.userAgent;
const isSafari = /Safari/.test(ua) && !/Chrome|Chromium|CriOS|Edg|OPR|Android/.test(ua);
const isFirefox = /Firefox|FxiOS/.test(ua);
const isSamsung = /SamsungBrowser/.test(ua);
const isEdge = /Edg/.test(ua);
```

`syncButtons`: `const installed = standalone(); buttons.forEach(btn => { btn.hidden = installed; });` But we also want to hide header button if prompt not available? No, always show instructions. On desktop, both show.

Maybe show "Installed" state in info card? Hide CTA and show hint "Aplikasi sudah terpasang..." if standalone. Buttons hidden and hint updated.
```js
const hint = document.getElementById('installHint');
if (hint) hint.textContent = installed ? 'DiceForge sudah berjalan sebagai aplikasi terpasang.' : ...
```
Keep original hint via defaultValue? Use textContent.

`beforeinstallprompt`:
```js
window.addEventListener('beforeinstallprompt', (event) => {
  event.preventDefault();
  installPrompt = event;
  syncButtons();
});
```
Don't need sync because already visible, but fine.

`appinstalled`: installPrompt = null; syncButtons(); maybe close dialog.

`button click`:
```js
async function promptInstall() {
  if (standalone()) return;
  if (!installPrompt) { openInstructions(); return; }
  const prompt = installPrompt;
  installPrompt = null;
  prompt.prompt();
  try { await prompt.userChoice; } catch {}
  syncButtons();
}
```
Note prompt.prompt() should be called synchronously in click handler before awaiting; it is. But if user dismisses, Chrome may not fire again. We can re-enable? `beforeinstallprompt` won't fire again until next page nav. That's okay. After dismissal, clicking again opens instructions? Actually installPrompt null, so instructions. Fine.

Could track outcome and show message. Not necessary.

`openInstructions`: create dialog once:
```js
function instructions() {
  if (isIOS()) return {
    title: 'Install di iPhone / iPad',
    intro: 'Tambahkan DiceForge ke Home Screen lewat Safari.',
    steps: ['Buka halaman ini di Safari.', 'Ketuk tombol Share (kotak dengan panah ke atas).', 'Pilih "Add to Home Screen" / "Tambah ke Layar Utama".', 'Ketuk "Add" untuk memasang.']
  };
  if (isAndroid()) { if Samsung... }
  if (isFirefox()) return { title:'Install di Firefox', intro:'Firefox belum mendukung pemasangan web app di semua perangkat.', steps: ['Gunakan Chrome, Edge, atau Safari untuk memasang.', ...] };
  return desktop instructions...
}
```

Dialog creation:
```js
function getDialog() {
  if (dialog) return dialog;
  dialog = document.createElement('dialog');
  dialog.className = 'install-dialog';
